// ✅ THREAD-SAFE SINGLETON (The modern C# way)
public class Logger
{
    // Lazy<T> guarantees thread safety automatically!
    private static readonly Lazy<Logger> _instance = new(() => new Logger());

    public static Logger Instance => _instance.Value;

    private Logger() { } // Private constructor
}

// ❌ OPEN-CLOSED VIOLATION
// Every time you add a new shape, you have to modify this core class!
public double CalculateArea(object shape) {
    if (shape is Circle c) return Math.PI * c.Radius * c.Radius;
    if (shape is Square s) return s.Side * s.Side;
    return 0;
}

// ✅ SOLID (Open for extension, closed for modification)
public interface IShape { double CalculateArea(); }
public class Circle : IShape { ... }

public double CalculateArea(IShape shape) {
    return shape.CalculateArea(); // Never needs to be modified again!
}

// ✅ DOMAIN LAYER (Pure C#, No EF Core allowed)
public interface IUserRepository {
    Task<User> GetById(int id);
}

// ✅ INFRASTRUCTURE LAYER (References Domain layer AND EF Core)
public class SqlUserRepository : IUserRepository {
    private readonly ApplicationDbContext _db;
    public async Task<User> GetById(int id) => await _db.Users.FindAsync(id);
}

// 1. THE COMMAND (Write) - Returns nothing, just mutates state
public record CreateUserCommand(string Name) : IRequest;

// 2. THE QUERY (Read) - Does not mutate state, just returns data
public record GetUserQuery(int Id) : IRequest<UserDto>;

// 3. ASP.NET CONTROLLER (Using MediatR)
[HttpPost] public async Task Create(CreateUserCommand cmd) => await _mediator.Send(cmd);
[HttpGet] public async Task<UserDto> Get(int id) => await _mediator.Send(new GetUserQuery(id));

// ❌ ANTI-PATTERN: The Generic Repository (Useless boilerplate)
public class GenericRepository<T> {
    public void Add(T entity) => _db.Set<T>().Add(entity);
}

// ✅ THE GOLD STANDARD: Specific Repository (Encapsulates complex logic)
public class UserRepository : IUserRepository {
    public async Task<List<User>> GetActiveAdminsAsync() {
        // Hides this complex SQL logic from the controller
        return await _db.Users.Where(u => u.IsActive && u.Role == "Admin").ToListAsync();
    }
}

